 void authenticate(String email,String password,boolean create,String fullName){
  if(!android.util.Patterns.EMAIL_ADDRESS.matcher(email).matches()){toast("Enter a valid email address.");return;}
  Toast.makeText(this,create?"Creating your account...":"Signing in...",Toast.LENGTH_SHORT).show();
  new Thread(()->{
   try{
    org.json.JSONObject data=new org.json.JSONObject();data.put("email",email);data.put("password",password);
    if(create){org.json.JSONObject meta=new org.json.JSONObject();meta.put("full_name",fullName);data.put("data",meta);}
    String endpoint=create?"/auth/v1/signup?redirect_to="+Uri.encode("thefirstcrush://login-callback"):"/auth/v1/token?grant_type=password";
    java.net.URL url=new java.net.URL("https://udwnmeqhwpnmwknjtssq.supabase.co"+endpoint);
    java.net.HttpURLConnection conn=(java.net.HttpURLConnection)url.openConnection();conn.setRequestMethod("POST");conn.setConnectTimeout(15000);conn.setReadTimeout(15000);conn.setDoOutput(true);conn.setRequestProperty("Content-Type","application/json");conn.setRequestProperty("apikey","sb_publishable_7NgXp6OxMzUITMkzAf18Dw_sd-7_61x");
    byte[] payload=data.toString().getBytes("UTF-8");conn.getOutputStream().write(payload);
    int status=conn.getResponseCode();java.io.InputStream stream=status>=200&&status<300?conn.getInputStream():conn.getErrorStream();java.io.ByteArrayOutputStream out=new java.io.ByteArrayOutputStream();byte[] buf=new byte[4096];int len;while((len=stream.read(buf))!=-1)out.write(buf,0,len);String response=new String(out.toByteArray(),"UTF-8");conn.disconnect();
    org.json.JSONObject result=new org.json.JSONObject(response);
    if(status>=200&&status<300){
     String access=result.optString("access_token","");String refresh=result.optString("refresh_token","");
     if(access.length()>0){getSharedPreferences("tfc_auth",MODE_PRIVATE).edit().putString("access_token",access).putString("refresh_token",refresh).putString("email",email).apply();}
     runOnUiThread(()->{if(create&&access.isEmpty()){toast("Account created. Check your email to confirm, then sign in.");}else{toast("Welcome to The First Crush!");screen("Home");String id=userId();if(!id.isEmpty())ensureProfile(id,create?fullName:"");}});
    }else{
     String msg=result.optString("msg",result.optString("message",result.optString("error_description","Sign-in failed. Please try again.")));
     if(msg.toLowerCase().contains("invalid login credentials"))msg="Email or password is incorrect.";
     if(msg.toLowerCase().contains("email not confirmed"))msg="Please confirm your email before signing in.";
     final String error=msg;runOnUiThread(()->toast(error));
    }
   }catch(Exception ex){runOnUiThread(()->toast("Connection error. Check your internet and try again."));}
  }).start();
 }
