 void pickupDetail(String line){base("Your Pickup Line");TextView hero=txt(line,23,Color.WHITE,true);hero.setGravity(17);hero.setPadding(dp(24),dp(30),dp(24),dp(30));GradientDrawable gd=new GradientDrawable(GradientDrawable.Orientation.TL_BR,new int[]{PINK,PURPLE,0xff24a6a0});gd.setCornerRadius(dp(26));hero.setBackground(gd);body.addView(hero,new LinearLayout.LayoutParams(-1,dp(240)));android.animation.ValueAnimator anim=android.animation.ValueAnimator.ofFloat(0f,1f);anim.setDuration(3200);anim.setRepeatCount(android.animation.ValueAnimator.INFINITE);anim.addUpdateListener(v->{float x=(Float)v.getAnimatedValue();int a=android.graphics.Color.rgb((int)(233-80*x),(int)(79+70*x),(int)(145+80*x));hero.setBackground(shape(a,26));});anim.start();body.addView(action("Copy line",()->{((android.content.ClipboardManager)getSystemService(CLIPBOARD_SERVICE)).setPrimaryClip(android.content.ClipData.newPlainText("Pickup line",line));toast("Copied!");}));body.addView(action("Share line",()->{Intent in=new Intent(Intent.ACTION_SEND);in.setType("text/plain");in.putExtra(Intent.EXTRA_TEXT,line);startActivity(Intent.createChooser(in,"Share pickup line"));}));body.addView(action("Back to categories",()->pickupHub()));}
