 void loadStories(LinearLayout target){
  api("GET","/rest/v1/stories?select=id,user_id,media_url,created_at,expires_at&expires_at=gt."+Uri.encode(java.time.Instant.now().toString())+"&order=created_at.desc&limit=100",null,res->{try{org.json.JSONArray a=new org.json.JSONArray(res);for(int i=0;i<a.length();i++){org.json.JSONObject item=a.getJSONObject(i);String uid=item.optString("user_id",""),url=item.optString("media_url",""),sid=item.optString("id","");api("GET","/rest/v1/profiles?id=eq."+uid+"&select=full_name,avatar_url",null,pr->{try{org.json.JSONArray pa=new org.json.JSONArray(pr);String name="Story";String av="";if(pa.length()>0){name=pa.getJSONObject(0).optString("full_name","Story");av=pa.getJSONObject(0).optString("avatar_url","");}LinearLayout tile=col();tile.setGravity(Gravity.BOTTOM);tile.setPadding(dp(8),dp(8),dp(8),dp(10));tile.setBackground(shape(0xffe4e6eb,16));tile.setClipToOutline(true);ImageView photo=new ImageView(this);photo.setScaleType(ImageView.ScaleType.CENTER_CROP);tile.addView(photo,new LinearLayout.LayoutParams(-1,0,1));loadAvatar(url,photo);TextView label=txt(name,12,Color.WHITE,true);tile.addView(label);LinearLayout.LayoutParams tp=new LinearLayout.LayoutParams(dp(108),dp(156));tp.rightMargin=dp(8);target.addView(tile,tp);tile.setOnClickListener(v->openStory(url,name,sid,uid));}catch(Exception ignored){}});}}catch(Exception e){toast("Could not load stories.");}});
 }
 void openStory(String url,String name,String storyId,String ownerId){ImageView image=new ImageView(this);image.setBackgroundColor(Color.BLACK);image.setScaleType(ImageView.ScaleType.FIT_CENTER);loadAvatar(url,image);new android.app.AlertDialog.Builder(this).setTitle(name+" · Story").setView(image).setPositiveButton("Close",null).setNeutralButton(ownerId.equals(userId())?"Delete":"OK",(d,w)->{if(ownerId.equals(userId()))api("DELETE","/rest/v1/stories?id=eq."+storyId+"&user_id=eq."+userId(),null,x->{toast("Story deleted.");screen("Home");});}).show();}
 void createStory(){pickedStoryPhoto=null;Intent i=new Intent(Intent.ACTION_GET_CONTENT);i.setType("image/*");startActivityForResult(Intent.createChooser(i,"Choose a photo for your story"),704);}
 void uploadStoryPhoto(String uid,java.util.function.Consumer<String> done){if(pickedStoryPhoto==null){toast("Choose a photo first.");return;}new Thread(()->{try{java.io.InputStream in=getContentResolver().openInputStream(pickedStoryPhoto);java.io.ByteArrayOutputStream out=new java.io.ByteArrayOutputStream();byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1)out.write(b,0,n);in.close();byte[] raw=out.toByteArray();android.graphics.Bitmap bm=BitmapFactory.decodeByteArray(raw,0,raw.length);if(bm==null)throw new Exception("Unsupported image.");int max=1600;float scale=Math.min(1f,Math.min((float)max/bm.getWidth(),(float)max/bm.getHeight()));android.graphics.Bitmap small=scale<1?android.graphics.Bitmap.createScaledBitmap(bm,Math.max(1,(int)(bm.getWidth()*scale)),Math.max(1,(int)(bm.getHeight()*scale)),true):bm;java.io.ByteArrayOutputStream jpg=new java.io.ByteArrayOutputStream();small.compress(android.graphics.Bitmap.CompressFormat.JPEG,85,jpg);if(small!=bm)small.recycle();bm.recycle();String path=uid+"/story_"+System.currentTimeMillis()+".jpg";java.net.HttpURLConnection c=(java.net.HttpURLConnection)new java.net.URL("https://udwnmeqhwpnmwknjtssq.supabase.co/storage/v1/object/stories/"+path).openConnection();c.setRequestMethod("POST");c.setDoOutput(true);c.setConnectTimeout(20000);c.setReadTimeout(30000);c.setRequestProperty("apikey","sb_publishable_7NgXp6OxMzUITMkzAf18Dw_sd-7_61x");c.setRequestProperty("Authorization","Bearer "+accessToken());c.setRequestProperty("Content-Type","image/jpeg");c.getOutputStream().write(jpg.toByteArray());int status=c.getResponseCode();if(status<200||status>=300)throw new Exception("Storage HTTP "+status);c.disconnect();String url="https://udwnmeqhwpnmwknjtssq.supabase.co/storage/v1/object/public/stories/"+path;runOnUiThread(()->done.accept(url));}catch(Exception e){runOnUiThread(()->toast("Story upload failed: "+e.getMessage()));}}).start();}
 void publishStory(){String uid=userId();if(uid.isEmpty())return;uploadStoryPhoto(uid,url->{try{org.json.JSONObject d=new org.json.JSONObject();d.put("user_id",uid);d.put("media_url",url);d.put("media_type","image");d.put("expires_at",java.time.Instant.now().plusSeconds(86400).toString());api("POST","/rest/v1/stories",d,res->{pickedStoryPhoto=null;toast("Your story is live for 24 hours!");screen("Home");});}catch(Exception e){toast("Could not publish story.");}});}
 void loadPosts(){final LinearLayout target=body;String me=userId();if(me.isEmpty()){target.addView(txt("Please sign in to load community posts.",14,MUTED,false));return;}api("GET","/rest/v1/posts?select=id,user_id,body,image_url,created_at&order=created_at.desc&limit=100",null,res->{if(body!=target)return;try{org.json.JSONArray arr=new org.json.JSONArray(res);if(arr.length()==0){target.addView(txt("No community posts yet. Be the first to share 💗",14,MUTED,false));return;}for(int i=0;i<arr.length();i++){org.json.JSONObject p=arr.getJSONObject(i);String pid=p.optString("id","");String uid=p.optString("user_id","");String content=p.optString("body","");String imageUrl=p.optString("image_url","");api("GET","/rest/v1/profiles?id=eq."+uid+"&select=full_name,username,avatar_url",null,pr->{if(body!=target)return;String who="Community member";String username="";String avatar="";try{org.json.JSONArray pa=new org.json.JSONArray(pr);if(pa.length()>0){org.json.JSONObject prof=pa.getJSONObject(0);who=prof.optString("full_name","").trim();username=prof.optString("username","").trim();avatar=prof.optString("avatar_url","").trim();if(who.isEmpty())who=username.isEmpty()?"Community member":username;}}catch(Exception ignored){}post(pid,uid,who,username,avatar,content,imageUrl,me.equals(uid),target);});}}catch(Exception e){toast("Could not load community posts: "+e.getMessage());}});}
 void post(String postId,String ownerId,String who,String username,String avatar,String content,String imageUrl,boolean mine,LinearLayout target){
  LinearLayout card=col();card.setPadding(dp(16),dp(14),dp(16),dp(12));card.setBackground(shape(Color.WHITE,20));LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(-1,-2);cp.topMargin=dp(12);target.addView(card,cp);
  LinearLayout header=row();ImageView pic=new ImageView(this);pic.setImageResource(android.R.drawable.sym_def_app_icon);pic.setScaleType(ImageView.ScaleType.CENTER_CROP);pic.setBackground(shape(0xffffe6f0,40));pic.setClipToOutline(true);LinearLayout.LayoutParams ap=new LinearLayout.LayoutParams(dp(44),dp(44));ap.rightMargin=dp(10);header.addView(pic,ap);if(!avatar.isEmpty())loadAvatar(avatar,pic);
  LinearLayout identity=col();identity.addView(txt(who.isEmpty()?"Community member":who,15,INK,true));if(username!=null&&!username.isEmpty()&&!username.equals(who))identity.addView(txt("@"+username.replace("@",""),12,MUTED,false));identity.addView(txt(mine?"Your post":"Community post",11,PURPLE,false));header.addView(identity,new LinearLayout.LayoutParams(0,-2,1));card.addView(header);
  View.OnClickListener openProfile=v->{if(!ownerId.isEmpty())viewUserProfile(ownerId);};pic.setOnClickListener(openProfile);identity.setOnClickListener(openProfile);
  View divider=new View(this);divider.setBackgroundColor(LINE);LinearLayout.LayoutParams dpv=new LinearLayout.LayoutParams(-1,dp(1));dpv.topMargin=dp(12);dpv.bottomMargin=dp(12);card.addView(divider,dpv);
  if(content!=null&&!content.isEmpty())card.addView(txt(content,16,INK,false));
  if(imageUrl!=null&&!imageUrl.isEmpty()){ImageView postImage=new ImageView(this);postImage.setAdjustViewBounds(true);postImage.setScaleType(ImageView.ScaleType.CENTER_CROP);LinearLayout.LayoutParams ip=new LinearLayout.LayoutParams(-1,dp(230));ip.topMargin=dp(10);card.addView(postImage,ip);loadAvatar(imageUrl,postImage);}
  TextView counts=txt("0 likes     0 comments     0 shares",12,MUTED,false);LinearLayout.LayoutParams countParams=new LinearLayout.LayoutParams(-1,dp(34));countParams.topMargin=dp(8);card.addView(counts,countParams);
  View line=new View(this);line.setBackgroundColor(LINE);LinearLayout.LayoutParams lineParams=new LinearLayout.LayoutParams(-1,dp(1));lineParams.bottomMargin=dp(2);card.addView(line,lineParams);
  LinearLayout actions=row();actions.setGravity(Gravity.CENTER);TextView like=socialAction("👍","Like");like.setOnClickListener(v->toggleLike(postId,like));actions.addView(like,new LinearLayout.LayoutParams(0,dp(46),1));
  TextView comment=socialAction("▢","Comment");comment.setOnClickListener(v->openComments(postId,counts,comment));actions.addView(comment,new LinearLayout.LayoutParams(0,dp(46),1));
  TextView share=socialAction("↗","Share");share.setOnClickListener(v->sharePost(postId,content,counts,share));actions.addView(share,new LinearLayout.LayoutParams(0,dp(46),1));card.addView(actions);
  LinearLayout more=row();more.setGravity(Gravity.RIGHT|Gravity.CENTER_VERTICAL);TextView save=action("♡ Save",()->toggleFavorite(postId,save));save.setTextSize(12);more.addView(save);if(mine){more.addView(action("✎ Edit",()->editPost(postId,content)));more.addView(action("Delete",()->deletePost(postId)));}else{more.addView(action("⚑ Report",()->reportPost(postId)));}card.addView(more);loadFavoriteState(postId,save);
  loadLikeState(postId,like);refreshPostCounts(postId,counts,like,comment,share);
 }
 TextView socialAction(String icon,String label){TextView t=txt(icon+"  "+label,13,0xff65676b,true);t.setGravity(Gravity.CENTER);t.setSingleLine(true);t.setPadding(dp(2),0,dp(2),0);t.setBackgroundColor(Color.WHITE);return t;}
 void loadFavoriteState(String postId,TextView button){String me=userId();api("GET","/rest/v1/favorites?select=post_id&user_id=eq."+me+"&post_id=eq."+postId+"&limit=1",null,res->{try{boolean saved=new org.json.JSONArray(res).length()>0;button.setText(saved?"♥ Saved":"♡ Save");}catch(Exception ignored){}});}
 void toggleFavorite(String postId,TextView button){String me=userId();button.setEnabled(false);api("GET","/rest/v1/favorites?select=post_id&user_id=eq."+me+"&post_id=eq."+postId+"&limit=1",null,res->{try{boolean saved=new org.json.JSONArray(res).length()>0;if(saved)api("DELETE","/rest/v1/favorites?user_id=eq."+me+"&post_id=eq."+postId,null,x->{button.setEnabled(true);button.setText("♡ Save");toast("Removed from saved posts.");});else{org.json.JSONObject d=new org.json.JSONObject();d.put("user_id",me);d.put("post_id",postId);api("POST","/rest/v1/favorites",d,x->{button.setEnabled(true);button.setText("♥ Saved");toast("Post saved.");});}}catch(Exception e){button.setEnabled(true);toast("Could not save this post.");}});}
 void reportPost(String postId){final String[] reasons={"Spam","Harassment or bullying","Hate speech","Nudity or sexual content","Violence or dangerous content","False information","Other"};new android.app.AlertDialog.Builder(this).setTitle("Report this post").setItems(reasons,(d,which)->{try{org.json.JSONObject row=new org.json.JSONObject();row.put("post_id",postId);row.put("reporter_id",userId());row.put("reason",reasons[which]);api("POST","/rest/v1/reports",row,res->toast("Report submitted. Thank you for helping keep the community safe."));}catch(Exception e){toast("Could not submit report.");}}).setNegativeButton("Cancel",null).show();}
 void editPost(String postId,String currentText){EditText input=field("Edit your post");input.setSingleLine(false);input.setMinHeight(dp(120));input.setText(currentText);new android.app.AlertDialog.Builder(this).setTitle("Edit post").setView(input).setNegativeButton("Cancel",null).setPositiveButton("Save",(d,w)->{String value=input.getText().toString().trim();if(value.isEmpty()||value.length()>280){toast("Post must contain 1–280 characters.");return;}try{org.json.JSONObject patch=new org.json.JSONObject();patch.put("body",value);patch.put("text",value);api("PATCH","/rest/v1/posts?id=eq."+postId+"&user_id=eq."+userId(),patch,res->{toast("Post updated.");screen("Home");});}catch(Exception e){toast("Could not update post.");}}).show();}
 void savedPosts(){base("Saved Posts");body.addView(txt("Your favourite community posts 💗",17,INK,true));api("GET","/rest/v1/favorites?select=post_id,created_at&user_id=eq."+userId()+"&order=created_at.desc&limit=100",null,res->{try{org.json.JSONArray ids=new org.json.JSONArray(res);if(ids.length()==0){body.addView(txt("No saved posts yet.",14,MUTED,false));return;}for(int i=0;i<ids.length();i++){String id=ids.getJSONObject(i).optString("post_id","");api("GET","/rest/v1/posts?select=id,user_id,body,image_url&id=eq."+id,null,p->{try{org.json.JSONArray a=new org.json.JSONArray(p);if(a.length()==0)return;org.json.JSONObject post=a.getJSONObject(0);String owner=post.optString("user_id","");String bodyText=post.optString("body","");LinearLayout card=col();card.setPadding(dp(12),dp(12),dp(12),dp(12));card.setBackground(shape(Color.WHITE,14));card.addView(txt(bodyText,15,INK,true));card.addView(action("Open profile",()->viewUserProfile(owner)));card.addView(action("Unsave",()->api("DELETE","/rest/v1/favorites?user_id=eq."+userId()+"&post_id=eq."+id,null,x->{toast("Removed.");savedPosts();})));body.addView(card);gap(body,8);}catch(Exception ignored){}});}}catch(Exception e){toast("Could not load saved posts.");}});}
 void refreshPostCounts(String postId,TextView counts,TextView like,TextView comment,TextView share){
  api("GET","/rest/v1/likes?select=user_id&post_id=eq."+postId+"&limit=1000",null,res->{try{org.json.JSONArray a=new org.json.JSONArray(res);boolean liked=false;for(int i=0;i<a.length();i++)if(userId().equals(a.getJSONObject(i).optString("user_id","")))liked=true;counts.setText(counts.getText().toString().replaceAll("[0-9]+ likes",a.length()+" likes"));like.setText(liked?"👍 Liked":"👍  Like");}catch(Exception ignored){}});
  api("GET","/rest/v1/comments?select=id&post_id=eq."+postId+"&limit=1000",null,res->{try{int n=new org.json.JSONArray(res).length();comment.setText("▢  Comment");String old=counts.getText().toString();counts.setText(old.replaceAll("[0-9]+ comments",n+" comments"));}catch(Exception ignored){}});
  api("GET","/rest/v1/post_shares?select=id&post_id=eq."+postId+"&limit=1000",null,res->{try{int n=new org.json.JSONArray(res).length();share.setText("↗  Share");String old=counts.getText().toString();counts.setText(old.replaceAll("[0-9]+ shares",n+" shares"));}catch(Exception ignored){}});
 }
 void openComments(String postId,TextView counts,TextView commentButton){
  LinearLayout box=col();box.setPadding(dp(12),dp(8),dp(12),dp(8));ScrollView scroll=new ScrollView(this);LinearLayout list=col();scroll.addView(list);box.addView(scroll,new LinearLayout.LayoutParams(-1,dp(280)));
  EditText input=field("Write a comment…");input.setSingleLine(false);input.setMinHeight(dp(48));LinearLayout.LayoutParams inputP=new LinearLayout.LayoutParams(-1,-2);inputP.topMargin=dp(10);box.addView(input,inputP);
  android.app.AlertDialog dialog=new android.app.AlertDialog.Builder(this).setTitle("Comments").setView(box).setNegativeButton("Close",null).setPositiveButton("Post",null).create();
  Runnable reload=()->{list.removeAllViews();api("GET","/rest/v1/comments?select=id,user_id,body,created_at&post_id=eq."+postId+"&order=created_at.asc&limit=200",null,res->{try{org.json.JSONArray arr=new org.json.JSONArray(res);if(arr.length()==0)list.addView(txt("No comments yet. Be the first 💗",13,MUTED,false));for(int i=0;i<arr.length();i++){org.json.JSONObject item=arr.getJSONObject(i);String uid=item.optString("user_id","");String bodyText=item.optString("body","");list.addView(txt("@" +(uid.length()>8?uid.substring(0,8):"user")+"  "+bodyText,14,INK,false));gap(list,8);}}catch(Exception e){toast("Could not load comments.");}refreshPostCounts(postId,counts,action("♡ Like",()->{}),commentButton,action("↗ Share",()->{}));});};
  dialog.setOnShowListener(v->{dialog.getButton(-1).setOnClickListener(b->{String bodyText=input.getText().toString().trim();if(bodyText.isEmpty()){toast("Write a comment first.");return;}if(bodyText.length()>1000){toast("Comment must be 1,000 characters or fewer.");return;}try{org.json.JSONObject d=new org.json.JSONObject();d.put("post_id",postId);d.put("user_id",userId());d.put("body",bodyText);dialog.getButton(-1).setEnabled(false);api("POST","/rest/v1/comments",d,res->{input.setText("");dialog.getButton(-1).setEnabled(true);reload.run();});}catch(Exception e){toast("Could not send comment.");}});reload.run();});dialog.show();
 }
 void sharePost(String postId,String content,TextView counts,TextView shareButton){
  String me=userId();if(me.isEmpty()){toast("Please sign in again.");return;}
  // Count a user's share only once per post; the unique constraint is (post_id, user_id).
  api("GET","/rest/v1/post_shares?select=id&post_id=eq."+postId+"&user_id=eq."+me+"&limit=1",null,found->{
   try{
    org.json.JSONArray existing=new org.json.JSONArray(found);
    if(existing.length()==0){
     org.json.JSONObject d=new org.json.JSONObject();d.put("post_id",postId);d.put("user_id",me);
     api("POST","/rest/v1/post_shares",d,res->{refreshPostCounts(postId,counts,action("♡ Like",()->{}),action("💬 Comment",()->{}),shareButton);});
    }else{
     refreshPostCounts(postId,counts,action("♡ Like",()->{}),action("💬 Comment",()->{}),shareButton);
    }
   }catch(Exception e){toast("Could not update share count.");}
  });
  Intent intent=new Intent(Intent.ACTION_SEND);intent.setType("text/plain");intent.putExtra(Intent.EXTRA_TEXT,(content==null?"":content)+"\n\nShared from The First Crush");startActivity(Intent.createChooser(intent,"Share post"));
 }
