 void uploadPostPhoto(String id,java.util.function.Consumer<String> done){if(pickedPostPhoto==null){done.accept("");return;}new Thread(()->{try{java.io.InputStream in=getContentResolver().openInputStream(pickedPostPhoto);java.io.ByteArrayOutputStream out=new java.io.ByteArrayOutputStream();byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1)out.write(b,0,n);in.close();byte[] raw=out.toByteArray();android.graphics.Bitmap bm=BitmapFactory.decodeByteArray(raw,0,raw.length);if(bm==null)throw new Exception("Unsupported image.");int max=1600;float scale=Math.min(1f,Math.min((float)max/bm.getWidth(),(float)max/bm.getHeight()));android.graphics.Bitmap small=scale<1?android.graphics.Bitmap.createScaledBitmap(bm,Math.max(1,(int)(bm.getWidth()*scale)),Math.max(1,(int)(bm.getHeight()*scale)),true):bm;java.io.ByteArrayOutputStream jpg=new java.io.ByteArrayOutputStream();small.compress(android.graphics.Bitmap.CompressFormat.JPEG,85,jpg);if(small!=bm)small.recycle();bm.recycle();String path=id+"/post_"+System.currentTimeMillis()+".jpg";java.net.HttpURLConnection c=(java.net.HttpURLConnection)new java.net.URL("https://udwnmeqhwpnmwknjtssq.supabase.co/storage/v1/object/post-images/"+path).openConnection();c.setRequestMethod("POST");c.setDoOutput(true);c.setConnectTimeout(20000);c.setReadTimeout(30000);c.setRequestProperty("apikey","sb_publishable_7NgXp6OxMzUITMkzAf18Dw_sd-7_61x");c.setRequestProperty("Authorization","Bearer "+accessToken());c.setRequestProperty("Content-Type","image/jpeg");c.setRequestProperty("x-upsert","true");c.getOutputStream().write(jpg.toByteArray());int status=c.getResponseCode();if(status<200||status>=300)throw new Exception("Storage HTTP "+status);c.disconnect();String url="https://udwnmeqhwpnmwknjtssq.supabase.co/storage/v1/object/public/post-images/"+path;runOnUiThread(()->done.accept(url));}catch(Exception e){runOnUiThread(()->toast("Photo upload failed: "+e.getMessage()));}}).start();}

