 void createPost(){base("Create post");postInput=field("Write something for your community...");postInput.setSingleLine(false);postInput.setMinHeight(dp(150));body.addView(postInput);postPhotoPreview=new ImageView(this);postPhotoPreview.setScaleType(ImageView.ScaleType.CENTER_CROP);postPhotoPreview.setBackground(shape(0xfff0f2f5,16));body.addView(postPhotoPreview,new LinearLayout.LayoutParams(-1,dp(180)));body.addView(action("▧ Add photo",()->choosePostPhoto()));body.addView(txt("Your post will be shared with the community.",12,MUTED,false));TextView share=primary("Share post");body.addView(share);share.setOnClickListener(v->{String content=postInput.getText().toString().trim();String uid=userId();if(uid.isEmpty()){toast("Your session is missing. Please sign in again.");login();return;}if(content.isEmpty()&&pickedPostPhoto==null){toast("Write text or choose a photo.");return;}if(content.length()>280){toast("Post must be 280 characters or fewer.");return;}share.setEnabled(false);share.setText("Sharing…");String fallback=getSharedPreferences("tfc_profile",MODE_PRIVATE).getString("full_name","");if(fallback.trim().isEmpty())fallback=getSharedPreferences("tfc_auth",MODE_PRIVATE).getString("email","").split("@")[0];final String defaultAuthor=fallback.trim().isEmpty()?"The First Crush member":fallback.trim();api("GET","/rest/v1/profiles?id=eq."+uid+"&select=full_name,username",null,profileRes->{String author=defaultAuthor;try{org.json.JSONArray profiles=new org.json.JSONArray(profileRes);if(profiles.length()>0){String full=profiles.getJSONObject(0).optString("full_name","").trim();String username=profiles.getJSONObject(0).optString("username","").trim();if(!full.isEmpty())author=full;else if(!username.isEmpty())author=username;}}catch(Exception ignored){}try{org.json.JSONObject d=new org.json.JSONObject();d.put("user_id",uid);d.put("body",content);d.put("text",content.isEmpty()?"📷 Photo":content);d.put("language","mixed");d.put("category","General");d.put("author_name",author);uploadPostPhoto(uid,image->{try{d.put("image_url",image);d.put("media_type",image.isEmpty()?"post":"photo");api("POST","/rest/v1/posts",d,res->{pickedPostPhoto=null;postPhotoPreview=null;toast("Post shared successfully!");screen("Home");});}catch(Exception ex){toast("Could not attach photo.");}});}catch(Exception e){share.setEnabled(true);share.setText("Share post");toast("Could not create post: "+e.getMessage());}});});body.addView(action("Cancel",()->screen("Home")));}
